def range_sum_updates(nums, queries):
    n = len(nums); bit = [0] * (n + 1); a = nums[:]
    def add(i, d):
        i += 1
        while i <= n: bit[i] += d; i += i & -i
    def pre(i):
        s = 0
        while i > 0: s += bit[i]; i -= i & -i
        return s
    for i, x in enumerate(a): add(i, x)
    out = []
    for t, x, y in queries:
        if t == 0: add(x, y - a[x]); a[x] = y
        else: out.append(pre(y + 1) - pre(x))
    return out

