vector<long long> rangeSumUpdates(vector<int>& a, vector<vector<int>>& qs) {
    int n = a.size(); vector<long long> bit(n + 1, 0), out;
    auto add = [&](int i, long long d) { for (i++; i <= n; i += i & -i) bit[i] += d; };
    auto pre = [&](int i) { long long s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; };
    for (int i = 0; i < n; i++) add(i, a[i]);
    for (auto& q : qs) { if (q[0] == 0) { add(q[1], (long long)q[2] - a[q[1]]); a[q[1]] = q[2]; } else out.push_back(pre(q[2] + 1) - pre(q[1])); }
    return out;
}
